// behaviour test for 0x0062EE80 map<long, CCharString> copy constructor: the copy gets its own header (red, parent = the copied root), an empty source gives root 0 and leftmost = rightmost = header, a non-empty one is cloned node by node with leftmost / rightmost at the copy's minimum / maximum, and the node count is copied
#include <cstdio>
#include <cstdlib>
struct Node { bool color; Node* parent; Node* left; Node* right; int key; };
struct Tree { Node* header; unsigned int count; };
static int gClones = 0;
static Node* Clone(Node* x) { Node* t = (Node*)std::malloc(sizeof(Node)); *t = *x; t->left = 0; t->right = 0; ++gClones; return t; }
static Node* Copy(Node* x, Node* p)                      // STLport _M_copy
{
    Node* top = Clone(x);
    top->parent = p;
    if (x->right) top->right = Copy(x->right, top);
    p = top; x = x->left;
    while (x != 0) {
        Node* y = Clone(x);
        p->left = y; y->parent = p;
        if (x->right) y->right = Copy(x->right, y);
        p = y; x = x->left;
    }
    return top;
}
static void CopyConstruct(Tree* self, const Tree& x)
{
    self->header = 0;
    self->header = (Node*)std::malloc(sizeof(Node));
    self->count = 0;
    Node* h = self->header;
    h->color = false;
    if (x.header->parent == 0) { h->parent = 0; h->left = h; h->right = h; }
